def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"[A-Z]+[0-9]*|[0-9]+|<=|>=|<>|[+\-*/(),:=<>]")
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "u-": 4,
        ":": 5,
    }

    def integer(text):
        negative = text.startswith("-")
        if negative:
            text = text[1:]
        value = 0
        for i in range(0, len(text), 9):
            chunk = text[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return -value if negative else value

    def parse(text):
        if not text.startswith("="):
            return ("num", integer(text))

        tokens = token_pattern.findall(text[1:])
        values = []
        operators = []

        def reduce_operator():
            op = operators.pop()
            if op == "u-":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                if op == ":":
                    values.append(("range", left[1], right[1]))
                else:
                    values.append(("bin", op, left, right))

        expecting_operand = True
        i = 0
        while i < len(tokens):
            token = tokens[i]

            if token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(("(", token, len(values)))
                i += 2  # Skip the function name and its opening parenthesis.
                expecting_operand = True
                continue

            if token == "(":
                operators.append(("(", None, len(values)))
                expecting_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                expecting_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, function, base = operators.pop()
                if function is not None:
                    args = values[base:]
                    del values[base:]
                    values.append(("func", function, args))
                expecting_operand = False
            elif token in precedence:
                op = "u-" if token == "-" and expecting_operand else token
                while operators and isinstance(operators[-1], str):
                    top = operators[-1]
                    if precedence[top] > precedence[op] or (
                        precedence[top] == precedence[op] and op != "u-"
                    ):
                        reduce_operator()
                    else:
                        break
                operators.append(op)
                expecting_operand = True
            elif token[0].isdigit():
                values.append(("num", integer(token)))
                expecting_operand = False
            else:
                values.append(("ref", token))
                expecting_operand = False
            i += 1

        while operators:
            reduce_operator()
        return values[0]

    def expand_arguments(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            first, second = arg[1], arg[2]
            left = min(ord(first[0]), ord(second[0]))
            right = max(ord(first[0]), ord(second[0]))
            top = min(int(first[1:]), int(second[1:]))
            bottom = max(int(first[1:]), int(second[1:]))
            for row in range(top, bottom + 1):
                for column in range(left, right + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("ref", name)

    def evaluate(node):
        tasks = [("eval", node)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "eval":
                current = task[1]
                node_kind = current[0]

                if node_kind == "num":
                    values.append(current[1])
                elif node_kind == "ref":
                    values.append((yield current[1]))
                elif node_kind == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", current[1]))
                elif node_kind == "bin":
                    tasks.append(("left", current[1], current[3]))
                    tasks.append(("eval", current[2]))
                else:
                    function, args = current[1], current[2]
                    if function == "IF":
                        tasks.append(("if", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        tasks.append(("aggregate", function, iter(expand_arguments(args)), None))

            elif kind == "neg":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif kind == "left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "right":
                right = values.pop()
                op, left = task[1], task[2]
                if isinstance(right, str):
                    values.append(right)
                elif op == "+":
                    values.append(left + right)
                elif op == "-":
                    values.append(left - right)
                elif op == "*":
                    values.append(left * right)
                elif op == "/":
                    if right == 0:
                        values.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        values.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    values.append(left == right)
                elif op == "<>":
                    values.append(left != right)
                elif op == "<":
                    values.append(left < right)
                elif op == "<=":
                    values.append(left <= right)
                elif op == ">":
                    values.append(left > right)
                else:
                    values.append(left >= right)

            elif kind == "if":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                function, arguments, accumulator = task[1:]
                argument = next(arguments, None)
                if argument is None:
                    values.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(("aggregate_value", function, arguments, accumulator))
                    tasks.append(("eval", argument))

            else:  # aggregate_value
                function, arguments, accumulator = task[1:]
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                else:
                    if accumulator is None:
                        accumulator = value
                    elif function == "SUM":
                        accumulator += value
                    elif function == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(("aggregate", function, arguments, accumulator))

        return values.pop()

    results = {}
    in_progress = set()

    for root in cells:
        if root in results:
            continue

        in_progress.add(root)
        stack = [(root, evaluate(parse(cells[root])))]
        incoming = None

        while stack:
            name, evaluator = stack[-1]
            try:
                reference = evaluator.send(incoming)
            except StopIteration as finished:
                stack.pop()
                in_progress.remove(name)
                results[name] = finished.value
                incoming = finished.value
                continue

            if reference not in cells:
                incoming = 0
            elif reference in results:
                incoming = results[reference]
            elif reference in in_progress:
                incoming = "#CYCLE!"
            else:
                in_progress.add(reference)
                stack.append((reference, evaluate(parse(cells[reference]))))
                incoming = None

    return {name: results[name] for name in cells}
